# demo_tty.r —— **第 2 层：彩色控制台**
#
# 这一层解决的问题是「**在一个字符界面上做版面**」：清屏、把光标挪到第几行第几列、
# 设前景/背景色。老 DOS 程序（菜单、表格、状态栏）全靠这几个原语拼出来。
#
# R 这一层**没有 conio/crt 绑定**（`Lib/r/console.r` 那几个 `console_*` 是文档性存根），
# 所以这里**直接输出 ANSI 转义序列** —— 那正是"支持彩色的控制台程序"：
#
#     清屏        ESC [ 2 J          ESC [ H
#     定位光标    ESC [ <行> ; <列> H
#     前景/背景   ESC [ 3x m / 4x m / 9x m / 10x m，256 色 38;5;N，真彩 38;2;r;g;b
#     复位        ESC [ 0 m
#
# ## ⚠ 本前端的两条限制（写 demo 时避开）
#
#   · **`cat` 只打印第一个实参** —— `cat("\x1b[31m", " 红 ")` 只会打出转义。
#     （`Examples/r/catch.r` 的文件头记着同一条。）所以**一个 `cat` 恰好一个实参**。
#   · **没有 `paste`**（`未定义的函数 'func_paste'`）⇒ 数字没法拼进字符串里，
#     坐标只能写成字面量。
#   · `\x1b` 在**字符串字面量里是支持的**，所以可以内联 ESC（本前端不认 `0x` 开头的
#     整数，颜色要写负数十进制 —— 那是绘图那一层的规矩，这里用不上）。
#
# ## 在哪儿能看到什么
#
# · **真终端**（`vmlcli … | cat -v`）：整套转义都生效。
# · **手机"命令行"页**：那一层把 stdout 里的 ANSI 转成仓库统一的 `«»` 中间格式
#   （`UI/Shared/AnsiMarkup.cs`），**只认 SGR（颜色/样式）**；光标定位（`ESC[…H`）
#   与清屏（`ESC[2J`）会被**吃掉** —— 这是刻意的有限子集（见
#   `Examples/c/ansi_colors.c` 的说明）。所以每行末尾都补了换行，
#   定位被吃掉时输出仍然一行一句、读得通。
#
# 跑法：命令行页输入  vml run examples/r/demo_tty.r

# ── 开场：清屏 + 回左上角 ───────────────────────────────────────
cat("\x1b[2J")
cat("\x1b[H")

# ── 标题条：蓝底白字（ESC[44;97m）──────────────────────────────
cat("\x1b[1;1H")
cat("\x1b[44;97m")
cat("  demo_tty (R) —— 彩色控制台 / ANSI 转义序列               ")
cat("\x1b[0m")
cat("\n")

cat("\x1b[2;1H")
cat("\x1b[90m")
cat("清屏 ESC[2J   定位 ESC[r;cH   颜色 ESC[3xm / ESC[4xm   复位 ESC[0m")
cat("\x1b[0m")
cat("\n")

# ── 标准 8 色前景（30–37）──────────────────────────────────────
cat("\x1b[4;1H")
cat("\x1b[1;37m")
cat("标准 8 色前景：")
cat("\x1b[0m")
cat("\n")

cat("\x1b[5;1H")
cat("\x1b[30m")
cat(" 30 黑 ")
cat("\x1b[0m")
cat("\x1b[31m")
cat(" 31 红 ")
cat("\x1b[0m")
cat("\x1b[32m")
cat(" 32 绿 ")
cat("\x1b[0m")
cat("\x1b[33m")
cat(" 33 黄 ")
cat("\x1b[0m")
cat("\x1b[34m")
cat(" 34 蓝 ")
cat("\x1b[0m")
cat("\x1b[35m")
cat(" 35 品红 ")
cat("\x1b[0m")
cat("\x1b[36m")
cat(" 36 青 ")
cat("\x1b[0m")
cat("\x1b[37m")
cat(" 37 白 ")
cat("\x1b[0m")
cat("\n")

# ── 亮色前景（90–97）────────────────────────────────────────────
cat("\x1b[6;1H")
cat("\x1b[90m")
cat(" 90 亮黑(灰) ")
cat("\x1b[0m")
cat("\x1b[91m")
cat(" 91 亮红 ")
cat("\x1b[0m")
cat("\x1b[92m")
cat(" 92 亮绿 ")
cat("\x1b[0m")
cat("\x1b[93m")
cat(" 93 亮黄 ")
cat("\x1b[0m")
cat("\x1b[94m")
cat(" 94 亮蓝 ")
cat("\x1b[0m")
cat("\x1b[95m")
cat(" 95 亮品红 ")
cat("\x1b[0m")
cat("\x1b[96m")
cat(" 96 亮青 ")
cat("\x1b[0m")
cat("\x1b[97m")
cat(" 97 亮白 ")
cat("\x1b[0m")
cat("\n")

# ── 背景色（40–47 / 100–107）───────────────────────────────────
cat("\x1b[8;1H")
cat("\x1b[1;37m")
cat("背景色：")
cat("\x1b[0m")
cat("\n")

cat("\x1b[9;1H")
cat("\x1b[41m")
cat(" 红底 ")
cat("\x1b[0m")
cat("\x1b[42m")
cat(" 绿底 ")
cat("\x1b[0m")
cat("\x1b[44m")
cat(" 蓝底 ")
cat("\x1b[0m")
cat("\x1b[46m")
cat(" 青底 ")
cat("\x1b[0m")
cat("\x1b[103m")
cat(" 亮黄底 ")
cat("\x1b[0m")
cat("\x1b[105m")
cat(" 亮品红底 ")
cat("\x1b[0m")
cat("\n")

# ── 样式（1 粗 / 2 暗 / 3 斜 / 4 下划线 / 9 删除线）─────────────
cat("\x1b[11;1H")
cat("\x1b[1;37m")
cat("样式：")
cat("\x1b[0m")
cat("\x1b[1m")
cat(" 粗体 ")
cat("\x1b[0m")
cat("\x1b[2m")
cat(" 暗淡 ")
cat("\x1b[0m")
cat("\x1b[3m")
cat(" 斜体 ")
cat("\x1b[0m")
cat("\x1b[4m")
cat(" 下划线 ")
cat("\x1b[0m")
cat("\x1b[9m")
cat(" 删除线 ")
cat("\x1b[0m")
cat("\n")

# ── 256 色（38;5;N）与真彩（38;2;r;g;b）─────────────────────────
cat("\x1b[13;1H")
cat("\x1b[1;37m")
cat("256 色 / 真彩：")
cat("\x1b[0m")
cat("\x1b[38;5;208m")
cat(" 256-208 橙 ")
cat("\x1b[0m")
cat("\x1b[38;5;46m")
cat(" 256-46 亮绿 ")
cat("\x1b[0m")
cat("\x1b[38;2;255;128;0m")
cat(" 真彩橙 ")
cat("\x1b[0m")
cat("\x1b[48;2;60;0;90m")
cat(" 真彩深紫底 ")
cat("\x1b[0m")
cat("\n")

# ── 循环画一条色带（12 格，颜色在 8 档里循环）──────────────────
# 「算出来的」那一格：取模 + 分支挑字面量色码（数字转不进字符串，见文件头）。
cat("\x1b[16;1H")
cat("\x1b[1;37m")
cat("循环画 12 格色带：")
cat("\x1b[0m")
cat("\n")

cat("\x1b[17;1H")
i <- 0
while (i < 12) {
  k <- i %% 8
  if (k == 0) {
    cat("\x1b[41m")
  }
  if (k == 1) {
    cat("\x1b[42m")
  }
  if (k == 2) {
    cat("\x1b[43m")
  }
  if (k == 3) {
    cat("\x1b[44m")
  }
  if (k == 4) {
    cat("\x1b[45m")
  }
  if (k == 5) {
    cat("\x1b[46m")
  }
  if (k == 6) {
    cat("\x1b[47m")
  }
  if (k == 7) {
    cat("\x1b[100m")
  }
  cat("   ")
  cat("\x1b[0m")
  i <- i + 1
}
cat("\n")

# ── 收尾：复位颜色 + 定位到第 20 行写结束语 ─────────────────────
cat("\x1b[0m")
cat("\x1b[20;1H")
cat("\x1b[1;32m")
cat("demo_tty 结束 —— 没有按键等待，画完即退出。")
cat("\x1b[0m")
cat("\n")
